query ApiAutocompleteGeoLocation($text: String!, $locationTypes: [GeoLocationType!]) {
  result: autocompleteGeoLocation(text: $text, locationTypes: $locationTypes) {
    ...AutocompleteLocationResultParts
    __typename
  }
}

fragment AutocompleteGeoLocationParts on GeoLocation {
  name
  type
  providerLocationId
  __typename
}

fragment AutocompleteLocationParts on AutocompleteLocation {
  name
  geoLocationPath {
    ...AutocompleteGeoLocationParts
    __typename
  }
  __typename
}

fragment AutocompleteLocationResultParts on AutocompleteLocationResult {
  suggestions {
    ...AutocompleteLocationParts
    __typename
  }
  __typename
}

mutation ApiSetFormValue($organizationHostedJobsPageName: String!, $formRenderIdentifier: String!, $path: String!, $value: JSON, $formDefinitionIdentifier: String) {
  setFormValue(
    organizationHostedJobsPageName: $organizationHostedJobsPageName
    formRenderIdentifier: $formRenderIdentifier
    path: $path
    value: $value
    formDefinitionIdentifier: $formDefinitionIdentifier
  ) {
    ...FormRenderParts
    __typename
  }
}

fragment JSONBoxParts on JSONBox {
  value
  __typename
}

fragment FileParts on File {
  id
  filename
  __typename
}

fragment FormFieldEntryParts on FormFieldEntry {
  id
  field
  fieldValue {
    ... on JSONBox {
      ...JSONBoxParts
      __typename
    }
    ... on File {
      ...FileParts
      __typename
    }
    ... on FileList {
      files {
        ...FileParts
        __typename
      }
      __typename
    }
    __typename
  }
  isRequired
  descriptionHtml
  isHidden
  __typename
}

fragment FormRenderParts on FormRender {
  id
  formControls {
    identifier
    title
    __typename
  }
  errorMessages
  formErrors {
    message
    fieldEntryId
    __typename
  }
  sections {
    title
    descriptionHtml
    fieldEntries {
      ...FormFieldEntryParts
      __typename
    }
    isHidden
    __typename
  }
  sourceFormDefinitionId
  __typename
}

mutation ApiCreateFileUploadHandle($organizationHostedJobsPageName: String!, $fileUploadContext: FileUploadContext!, $filename: String!, $contentType: String!, $contentLength: Int!) {
  fileUploadHandle: createFileUploadHandle(
    organizationHostedJobsPageName: $organizationHostedJobsPageName
    fileUploadContext: $fileUploadContext
    filename: $filename
    contentType: $contentType
    contentLength: $contentLength
  ) {
    handle
    url
    fields
    __typename
  }
}

